	if (heightFraction < 0.0 || heightFraction > 1.0) {
		return 0.0;
	}

	let n = normalize(pos - ctx.earthCenter);
	// triplanar fixes 2d texture stretching on sphere
	let weatherPos = pos + ctx.time * ctx.windSpeed;
	let weatherScale = 1.0 / ctx.weatherMapScale;
