	let base_uv = pos / ctx.baseNoiseScale + ctx.time * ctx.windSpeed / ctx.baseNoiseScale;
	let baseN = textureSampleLevel(baseNoise, noiseSamp, base_uv, 0.0);
	let lowFBM = baseN.g * 0.625 + baseN.b * 0.25 + baseN.a * 0.125;
	var baseCloud = remap(baseN.r, -(1.0 - lowFBM), 1.0, 0.0, 1.0);

